GAMES_ADDED_COLUMNS = [("home_classification", "text"), ("away_classification", "text"), ("completed", "boolean")]


def init_schema(con: duckdb.DuckDBPyConnection) -> None:
    for stmt in DDL:
        con.execute(stmt)
    for name, typ in GAMES_ADDED_COLUMNS:
        con.execute(f"alter table games add column if not exists {name} {typ}")


def backup_db(path: Path, operation: str) -> Path:
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    out = path.parent / f"cfb_benchmarks_before_{operation}_{stamp}.duckdb"

