def iterate_weeks(fetch: Callable[[int, int, str], list[dict]], season: int, config: Config, store: Callable,
                  on_week=None, con: duckdb.DuckDBPyConnection | None = None) -> int:
    """Regular weeks 1..max then postseason 1..max, stopping each season type at the first empty week.

    A response whose row count sits on a known cap is accepted only when it still covers every expected game.
    A stored week missing more than MAX_MISSING_SHARE of its expected games raises CoverageError; a smaller gap
    is passed to on_week(season, season_type, week, stored, missing_game_ids) for the receipt."""
    total = 0
    for season_type, max_weeks in (("regular", config.metrics.max_regular_weeks), ("postseason", config.metrics.max_postseason_weeks)):
        for week in range(1, max_weeks + 1):
            rows = fetch(season, week, season_type)
            expected = expected_games(con, season, week, season_type) if con is not None else set()
            seen = {r.get("gameId") for r in rows}
            if len(rows) in config.metrics.cap_row_counts and not expected <= seen:
                raise TruncationError(season, week, season_type, len(rows))
            if not rows:
                break
            stored = store(season, week, season_type, rows)
            missing = sorted(expected - seen)
            if expected and len(missing) / len(expected) > MAX_MISSING_SHARE:
                raise CoverageError(season, week, season_type, missing, len(expected))
            total += stored
            if on_week:
                on_week(season, season_type, week, stored, missing)
    return total


